"use strict";const fs=require("fs");const path=require("path");module.exports=function(defaultFuncs,api,ctx){return function enableAutoSaveAppState(options){options=options||{};const filePath=options.filePath||path.join(process.cwd(),"appstate.json");const interval=options.interval||5*60*1e3;const saveOnLogin=options.saveOnLogin!==false;async function saveAppState(){try{const appState=api.getAppState?api.getAppState():null;if(!appState||Array.isArray(appState)&&appState.length===0){return}const payload=Array.isArray(appState)?appState:appState.appState||appState;fs.writeFileSync(filePath,JSON.stringify(payload,null,2),"utf8")}catch(_){}}let immediateTimer=null;if(saveOnLogin){immediateTimer=setTimeout(()=>{saveAppState();immediateTimer=null},2e3)}const timerId=setInterval(saveAppState,interval);if(!ctx._autoSaveIntervals)ctx._autoSaveIntervals=[];ctx._autoSaveIntervals.push(timerId);function disable(){if(immediateTimer){clearTimeout(immediateTimer);immediateTimer=null}clearInterval(timerId);if(ctx._autoSaveIntervals){const i=ctx._autoSaveIntervals.indexOf(timerId);if(i!==-1)ctx._autoSaveIntervals.splice(i,1)}}return disable}};
